UsbRpsPrintRequest _qolipCellUsbPrintJob(QolipCellQr cellQr) {
  return UsbRpsPrintRequest(
    epc: cellQr.qrPayload,
    itemCode: cellQr.qrPayload,
    itemName: _qolipCellLabel(cellQr),
