String _qolipCellLabel(QolipCellQr cellQr) {
  final row = cellQr.rowLetter.trim().toUpperCase();
  if (row.isNotEmpty && cellQr.columnNumber > 0) {
    return '$row${cellQr.columnNumber}';
  }
  return cellQr.locationLabel.trim();
}

